package com.meshcrossway.android;

import java.nio.charset.StandardCharsets;
import java.util.*;
import static com.meshcrossway.android.MeshData.*;

/** Companion 1.18 frame goldens, settings readback and contact/ACK lifecycle regressions. */
public final class McIntegrationTest {
    static int checks;static long clock=100;
    static final long ADVERT=1700000000L,MODIFIED=1794337200L;
    static final class Events implements ProtocolClient.Listener {
        final List<Message> messages=new ArrayList<>();final List<String> delivery=new ArrayList<>();final List<Node> updates=new ArrayList<>();
        public void node(Node n){updates.add(new Node(n));}public void channel(Channel c){}public void message(Message m){messages.add(m);}public void delivery(String uid,String value){delivery.add(uid+":"+value);}
    }
    static void check(boolean yes,String label){checks++;if(!yes)throw new AssertionError(label);}
    static void rejects(Runnable action,String label){boolean yes=false;try{action.run();}catch(IllegalArgumentException e){yes=true;}check(yes,label);}
    static void put(byte[] data,int offset,String value){byte[] text=value.getBytes(StandardCharsets.UTF_8);System.arraycopy(text,0,data,offset,text.length);}
    static byte[] self(int power,int maximum,int acks,String name){byte[] f=new byte[58+name.getBytes(StandardCharsets.UTF_8).length];f[0]=5;f[1]=1;f[2]=(byte)power;f[3]=(byte)maximum;f[4]=1;f[44]=(byte)acks;f[45]=1;f[46]=0x15;Wire.put32(f,48,915000);Wire.put32(f,52,62500);f[56]=7;f[57]=5;put(f,58,name);return f;}
    static byte[] metadata(boolean repeat,int mode){byte[] f=new byte[82];f[0]=13;f[1]=14;f[2]=100;f[3]=1;put(f,8,"15 Oct 2026");put(f,20,"Heltec V3");put(f,60,"1.18.0");f[80]=(byte)(repeat?1:0);f[81]=(byte)mode;return f;}
    static byte[] contact(int code,int key){byte[] f=new byte[148];f[0]=(byte)code;f[1]=(byte)key;f[33]=1;f[35]=(byte)255;put(f,100,"Peer");Wire.put32(f,132,ADVERT);Wire.put32(f,144,MODIFIED);return f;}
    static ProtocolClient.Command take(ProtocolClient c){ProtocolClient.Command q=c.next(clock++);if(q==null)throw new AssertionError("Expected a queued command");c.written(clock++);return q;}
    static void receive(ProtocolClient c,byte[] frame){c.receive(frame,clock++);}
    static ProtocolClient fresh(Events e,int power,int maximum,int acks,boolean repeat){
        ProtocolClient c=new ProtocolClient(RadioProfile.MESHCORE,42,e);take(c);receive(c,metadata(repeat,1));take(c);receive(c,self(power,maximum,acks,"Audit"));take(c);receive(c,new byte[]{2,1,0,0,0});receive(c,contact(3,7));receive(c,new byte[]{4,0,0,0,0});take(c);byte[] ch=new byte[50];ch[0]=18;put(ch,2,"Test");Arrays.fill(ch,34,50,(byte)1);receive(c,ch);take(c);receive(c,new byte[]{10});c.next(clock++);if(!c.ready)throw new AssertionError("Bootstrap failed");return c;
    }
    static ProtocolClient fresh(){return fresh(new Events(),22,30,0,true);}
    static void finish(ProtocolClient c,byte[] identity,byte[] device,byte[] scope,byte[] approved){
        int count=0;while(c.mcAdmin.edit!=null&&c.mcAdmin.edit.deadline!=Long.MAX_VALUE){if(++count>=12)throw new AssertionError("Verification did not terminate");ProtocolClient.Command q=take(c);int op=q.data[0]&255;
            if(!q.mcVerification)throw new AssertionError("Verification resent a SET");
            if(op==1)receive(c,identity);else if(op==22)receive(c,device);else if(op==64)receive(c,scope);else if(op==30)receive(c,approved==null?new byte[]{1,2}:approved);else if(op==5){byte[] now={9,0,0,0,0};Wire.put32(now,1,1794337201);receive(c,now);}else throw new AssertionError("Unexpected verification opcode "+op);
        }
        c.next(clock++);
    }
    static void ack(ProtocolClient c){receive(c,new byte[]{0});}
    public static void main(String[] args){
        checks=0;clock=100;
        ProtocolClient c=fresh();String original=c.localName;c.setName("RenBrant");check(c.localName.equals(original),"Name remains confirmed value before transmission");ProtocolClient.Command q=take(c);check(q.data[0]==8,"Name SET opcode");ack(c);check(c.mcAdmin.edit!=null,"ACK alone does not confirm a save");finish(c,self(22,30,0,"RenBrant"),metadata(true,1),new byte[]{28},null);check(c.mcAdmin.edit==null&&c.mcAdmin.error.isEmpty()&&c.localName.equals("RenBrant"),"Name is confirmed by fresh readback");
        c=fresh();c.setName("New");take(c);receive(c,new byte[]{1,6});check(c.ready&&c.mcAdmin.edit==null&&!c.mcAdmin.error.isEmpty()&&c.localName.equals("Audit"),"Ordinary settings ERR preserves model and connection");
        c=fresh();c.setName("New");take(c);ack(c);finish(c,self(22,30,0,"Other"),metadata(true,1),new byte[]{28},null);check(c.mcAdmin.error.contains("Node name")&&c.localName.equals("Other"),"Mismatched readback reports actual radio values");
        for(boolean repeat:new boolean[]{false,true}){c=fresh(new Events(),22,30,0,repeat);c.setRadioAndPath(915.5,125,9,6,2);q=take(c);check(q.data.length==12&&q.data[11]==(repeat?1:0),"Radio edit preserves repeat state");ack(c);q=take(c);check(Arrays.equals(q.data,new byte[]{61,0,2}),"Preset radio/path is one serialized transaction");ack(c);byte[] changed=self(22,30,0,"Audit");Wire.put32(changed,48,915500);Wire.put32(changed,52,125000);changed[56]=9;changed[57]=6;finish(c,changed,metadata(repeat,2),new byte[]{28},null);check(c.mcAdmin.error.isEmpty()&&c.frequencyMhz==915.5&&c.pathHashMode==2,"Compound radio/path readback confirms");}
        c=fresh();c.setRadio(915,62.5,7,5);take(c);ack(c);finish(c,self(22,30,0,"Audit"),metadata(false,1),new byte[]{28},null);check(c.mcAdmin.error.contains("Repeat mode"),"Unexpected repeat drift is not confirmed");
        ProtocolClient limits=fresh();rejects(()->limits.setName("a".repeat(32)),"32 ASCII bytes rejected");rejects(()->limits.setName("é".repeat(16)),"32 UTF8 bytes rejected");rejects(()->limits.setRadio(Double.NaN,125,7,5),"Nonfinite radio value rejected");rejects(()->limits.setLocation(Double.NaN,Double.NaN),"Nonfinite location rejected");rejects(()->limits.setRadio(915,Double.POSITIVE_INFINITY,7,5),"Infinite bandwidth rejected");rejects(()->limits.setTxPower(31),"Advertised maximum enforced");rejects(()->limits.setTxPower(-10),"Signed lower bound enforced");limits.setName("é".repeat(15));check(limits.mcAdmin.edit!=null,"30 UTF8 bytes accepted without truncation");
        c=fresh(new Events(),-5,30,0,true);check(c.txPower==-5&&c.hasTxPower,"Negative power decoded as signed with explicit presence");c.setTxPower(27);take(c);ack(c);finish(c,self(27,30,0,"Audit"),metadata(true,1),new byte[]{28},null);check(c.mcAdmin.error.isEmpty()&&c.txPower==27,"Power above 22 supported up to device maximum");
        c=fresh(new Events(),22,30,3,true);c.setOtherParams(c.manualAddContacts,c.telemetryModes,0,c.multiAcks);q=take(c);check(q.data[4]==3,"Privacy edit preserves integer ACK count");ack(c);byte[] privacy=self(22,30,3,"Audit");privacy[45]=0;finish(c,privacy,metadata(true,1),new byte[]{28},null);check(c.mcAdmin.error.isEmpty()&&c.mcExtraAcks==3,"Raw count readback verifies");
        c=fresh();c.setLocation(39.9292,-104.9259);take(c);ack(c);byte[] location=self(22,30,0,"Audit");Wire.put32(location,36,39929200);Wire.put32(location,40,-104925900);finish(c,location,metadata(true,1),new byte[]{28},null);check(c.mcAdmin.error.isEmpty()&&c.hasLocation,"Coordinate readback verifies signed microdegrees");
        c=fresh();c.setDefaultFloodScope("#test",new byte[16]);take(c);ack(c);byte[] region=new byte[48];region[0]=28;put(region,1,"#test");finish(c,self(22,30,0,"Audit"),metadata(true,1),region,null);check(c.mcAdmin.error.isEmpty()&&c.defaultFloodScope.equals("#test"),"Scope name and key readback verify");
        c=fresh();c.clearDefaultFloodScope();take(c);ack(c);finish(c,self(22,30,0,"Audit"),metadata(true,1),region,null);check(!c.mcAdmin.error.isEmpty(),"Nonempty scope cannot confirm a clear");
        c=fresh();c.clearDefaultFloodScope();take(c);ack(c);finish(c,self(22,30,0,"Audit"),metadata(true,1),new byte[]{28},null);check(c.mcAdmin.error.isEmpty(),"Empty scope confirms a clear");
        c=fresh();c.setDeviceTime(1794337200);take(c);ack(c);finish(c,self(22,30,0,"Audit"),metadata(true,1),new byte[]{28},null);check(c.mcAdmin.error.isEmpty(),"Device clock verifies with bounded elapsed-time tolerance");
        Events contacts=new Events();c=fresh(contacts,22,30,0,true);c.manualAddContacts=true;receive(c,contact(138,8));String discovered=Wire.hex(Arrays.copyOfRange(contact(138,8),1,33));check(!c.nodes.containsKey(discovered)&&c.mcDiscoveries.containsKey(discovered),"Discovered does not imply radio approval");Node candidate=c.mcDiscoveries.get(discovered);check(candidate.mcState==ProtocolClient.MC_DISCOVERED&&!candidate.mcRaw.isEmpty(),"Discovery retains approval metadata");c.approveMcContact(candidate);q=take(c);check(q.data[0]==9,"Explicit approval sends ADD_UPDATE_CONTACT");ack(c);finish(c,self(22,30,0,"Audit"),metadata(true,1),new byte[]{28},contact(3,8));check(c.nodes.containsKey(discovered)&&!c.mcDiscoveries.containsKey(discovered)&&c.mcAdmin.error.isEmpty(),"Approval requires successful contact lookup");
        c.removeMcContact(discovered);q=take(c);check(q.data[0]==15,"Explicit removal uses radio command");ack(c);finish(c,self(22,30,0,"Audit"),metadata(true,1),new byte[]{28},null);check(!c.nodes.containsKey(discovered)&&c.mcAdmin.error.isEmpty(),"Removal verifies NOT_FOUND without disconnect");check(contacts.updates.stream().anyMatch(n->n.id.equals(discovered)&&n.mcState==ProtocolClient.MC_RETIRED),"Historical node remains available for persistence");
        c=fresh();Node peer=c.nodes.values().iterator().next();byte[] deleted=new byte[33];deleted[0]=(byte)143;System.arraycopy(Wire.unhex(peer.id),0,deleted,1,32);receive(c,deleted);check(!c.nodes.containsKey(peer.id),"CONTACT_DELETED invalidates send eligibility");final ProtocolClient removed=c;final Node retired=peer;rejects(()->removed.send(Target.node(retired),"test",1,clock),"Cannot send to retired contact");
        c=fresh();c.refreshContacts();take(c);receive(c,new byte[]{2,0,0,0,0});receive(c,new byte[]{4,0,0,0,0});check(c.nodes.isEmpty()&&c.ready,"Empty full refresh retires unseen contacts while staying ready");
        c=fresh();check(c.nodes.values().iterator().next().heard==MODIFIED,"Contact receiver activity replaces sender advert creation time");peer=c.nodes.values().iterator().next();long before=peer.heard;byte[] dm=new byte[18];dm[0]=7;System.arraycopy(Wire.unhex(peer.id),0,dm,1,6);Wire.put32(dm,9,MODIFIED);put(dm,13,"hello");receive(c,dm);check(c.nodes.get(peer.id).heard>before,"Live DM advances local receipt activity");
        c=fresh();c.mcBacklogDrained=false;peer=c.nodes.values().iterator().next();long previous=peer.heard;receive(c,dm);check(c.nodes.get(peer.id).heard==previous&&c.mcDeferredContacts.contains(peer.id),"Initial backlog requests receiver metadata without inventing fresh RF activity");
        c=fresh();receive(c,new byte[]{(byte)144});check(c.mcFullContacts&&c.mcError.contains("full"),"Contacts-full condition is visible");
        c=fresh();c.firmwareCode=3;int size=c.commands.size();check(!c.requestStats(1)&&!c.requestDefaultFloodScope()&&c.commands.size()==size,"Unsupported reads are not sent to old firmware");final ProtocolClient old=c;rejects(()->old.setPathHashMode(2),"Old path editor cannot send unsupported command");
        c=fresh();c.requestStats(1);c.requestStats(1);check(c.commands.size()==1,"Duplicate settings-page reads coalesce");take(c);receive(c,new byte[]{1,1});check(c.ready&&!c.mcError.isEmpty()&&!c.requestStats(1),"Read rejection remains local and stops render-driven retry loops");c.retryMcReads();check(c.requestStats(1),"Explicit refresh clears a failed-read guard");
        Events delivery=new Events();c=fresh(delivery,22,30,0,true);peer=c.nodes.values().iterator().next();Message message=c.send(Target.node(peer),"late ACK",1,clock);take(c);byte[] accepted=new byte[10];accepted[0]=6;Wire.put32(accepted,2,1234);Wire.put32(accepted,6,5000);receive(c,accepted);c.next(clock++);clock+=5002;c.next(clock++);
        check(delivery.delivery.contains(message.uid+":uncertain")&&!c.mcLateSent.isEmpty(),"Estimated timeout retains bounded ACK correlation");byte[] confirmed=new byte[9];confirmed[0]=(byte)130;Wire.put32(confirmed,1,1234);receive(c,confirmed);check(delivery.delivery.contains(message.uid+":delivered")&&c.mcLateSent.isEmpty(),"Valid late ACK reconciles delivery");
        Events acrossReconnect=new Events();c=fresh(acrossReconnect,22,30,0,true);peer=c.nodes.values().iterator().next();message=c.send(Target.node(peer),"reconnect ACK",2,clock);take(c);receive(c,accepted);c.next(clock++);List<ProtocolClient.Sent> pending=c.mcRetainDeliveries(clock);
        Events restoredEvents=new Events();ProtocolClient reconnected=fresh(restoredEvents,22,30,0,true);reconnected.mcRestoreDeliveries(pending,clock);receive(reconnected,confirmed);check(restoredEvents.delivery.contains(message.uid+":delivered"),"ACK correlation survives reconnect to the same radio");
        Events zero=new Events();c=fresh(zero,22,30,0,true);peer=c.nodes.values().iterator().next();message=c.send(Target.node(peer),"zero hash",3,clock);take(c);Wire.put32(accepted,2,0);receive(c,accepted);c.next(clock++);Wire.put32(confirmed,1,0);receive(c,confirmed);check(zero.delivery.contains(message.uid+":delivered"),"A zero-valued known ACK hash is not confused with missing correlation");
        c=fresh();c.setTxPower(20);take(c);McAdmin.Edit interrupted=c.mcAdmin.edit;ProtocolClient restored=fresh();restored.mcAdmin.restore(interrupted);restored.mcAdmin.ready();finish(restored,self(20,30,0,"Audit"),metadata(true,1),new byte[]{28},null);check(restored.mcAdmin.edit==null&&restored.mcAdmin.error.isEmpty(),"Reconnect verifies a submitted SET without resending it");
        c=fresh();c.setTxPower(20);take(c);interrupted=c.mcAdmin.edit;ProtocolClient once=fresh();once.mcAdmin.restore(interrupted);once.mcAdmin.ready();q=take(once);check(q.data[0]==1&&q.mcVerification,"Recovery issues only a GET");once.mcAdmin.timeout(interrupted);
        ProtocolClient twice=fresh();twice.mcAdmin.restore(interrupted);twice.mcAdmin.ready();check(twice.mcAdmin.edit!=null&&twice.mcAdmin.edit.deadline==Long.MAX_VALUE&&twice.commands.isEmpty(),"Repeated failed recovery pauses instead of reconnecting endlessly");twice.mcAdmin.verify();finish(twice,self(20,30,0,"Audit"),metadata(true,1),new byte[]{28},null);check(twice.mcAdmin.error.isEmpty(),"Explicit check recovers a paused save with GET only");
        c=fresh();c.setRadioAndPath(916,125,9,5,2);take(c);ack(c);take(c);receive(c,new byte[]{1,6});check(c.mcAdmin.edit==null&&!c.mcAdmin.error.isEmpty()&&c.ready,"Partial multi-command rejection unlocks controls without a disconnect");q=take(c);check(q.data[0]==1,"Partial save is followed by current radio readback");byte[] applied=self(22,30,0,"Audit");Wire.put32(applied,48,916000);Wire.put32(applied,52,125000);applied[56]=9;receive(c,applied);q=take(c);check(q.data[0]==22,"Repeat/path state is also refreshed after partial failure");receive(c,metadata(true,1));check(c.frequencyMhz==916&&c.pathHashMode==1&&!c.mcAdmin.error.isEmpty(),"Display reflects actual partially applied values while retaining rejection notice");
        c=fresh();c.requestMcSelf();take(c);byte[] broken=Arrays.copyOf(self(22,30,0,"é".repeat(16)),58+31);receive(c,broken);check(c.ready&&c.mcNameNeedsRepair,"A legacy truncated UTF8 name remains connectable for repair");c.setName("Repaired");take(c);ack(c);finish(c,self(22,30,0,"Repaired"),metadata(true,1),new byte[]{28},null);check(!c.mcNameNeedsRepair&&c.localName.equals("Repaired"),"Saving a legal name clears the repair warning after verification");
        c=fresh();clock+=20001;q=take(c);check(q.data[0]==10,"Idle backlog poll");receive(c,new byte[]{27,0,0,0,0,0,0,0,0});q=take(c);check(q.data[0]==10,"Unsupported channel-data item immediately continues draining");receive(c,new byte[]{10});c.next(clock++);
        c=fresh();c.setName("Cancelled");c.mcAdmin.discard();check(c.commands.stream().noneMatch(cmd->cmd.data[0]==8)&&c.localName.equals("Audit"),"Discard before dispatch cannot send the queued SET");
        System.out.println("MeshCore audit regressions: "+checks+" checks passed");
    }
}
